/**
 * Where item strings keep their client classification tuple, whose first word is the item's
 * class key. Authored gear keeps its base's tuple, so the key names its class where the lists,
 * which hold only stock hashes, cannot.
 */
inline constexpr std::size_t kClassKeyOffset = 0xB8;
/** @return The class a stock hash is listed under: 0 Titan, 1 Hunter, 2 Warlock, 3 none. */
inline std::uint8_t find(std::uint32_t hash) noexcept {
    if (std::binary_search(std::begin(titan), std::end(titan), hash)) return 0;
    if (std::binary_search(std::begin(hunter), std::end(hunter), hash)) return 1;
    if (std::binary_search(std::begin(warlock), std::end(warlock), hash)) return 2;
    return 3;
}
/** @return The class an item's strings name by their class key, or 3 when they name none. */
inline std::uint8_t from_item_strings(std::span<const std::byte> strings) noexcept {
    std::uint32_t key{};
    if (strings.size() < kClassKeyOffset + sizeof key) return 3;
    std::memcpy(&key, strings.data() + kClassKeyOffset, sizeof key);
    switch (key) {
    case 0xD60E6BA5U: return 0;
    case 0xD74EBFB3U: return 1;
    case 0x82E15A90U: return 2;
    default: return 3;
    }
}
